[IO.File]::WriteAllText((Join-Path $PWD 'stop-and-fetch.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Starts a surl on the port in the first argument, fetches from it, stops it, and fetches`n# again, printing the status and curl's exit code each time. The running server holds`n# site, so this one serves a copy.`nport=`$1`ncp -r site live`nsurl -s --directory live http://127.0.0.1:`$port/ >/dev/null 2>&1 &`npid=`$!`nuntil curl -s -o /dev/null http://127.0.0.1:`$port/hello.txt; do sleep 0.2; done`ncurl -s -w `"%{http_code} %{exitcode}\n`" -o /dev/null http://127.0.0.1:`$port/hello.txt`nkill `$pid`n# Give the port a moment to close, then ask once more.`nwhile curl -s -o /dev/null http://127.0.0.1:`$port/hello.txt; do sleep 0.2; done`ncurl -s -w `"%{http_code} %{exitcode}\n`" -o /dev/null http://127.0.0.1:`$port/hello.txt`nexit 0`n")
